sys_ui_action.script:
(function executeAction(current, action) {
    try {
        // 增强调试信息
        gs.info("[EasyT] === 开始处理Return for Update操作 ===");
        gs.info("[EasyT] 当前审批记录: " + current.getDisplayValue());
        gs.info("[EasyT] 当前审批记录sys_id: " + current.sys_id);
        gs.info("[EasyT] document_id: " + current.document_id); // 改用document_id
        gs.info("[EasyT] 当前审批记录状态: " + current.state);

        // 1. 更新审批记录状态
        current.state = 'requested';
        current.comments = "Returned for updates: " + (current.comments || "");
        var approvalUpdate = current.update();
        gs.info("[EasyT] 审批记录更新结果: " + approvalUpdate);

        // 2. 更新原始请求记录（使用document_id）
        var requestRec = new GlideRecord('x_1770592_easy_t_0_my_asset_request');
        if (requestRec.get(current.document_id)) { // 关键修改点
            gs.info("[EasyT] 找到关联的请求记录: " + requestRec.getDisplayValue());
            gs.info("[EasyT] 当前请求记录状态: " + requestRec.my_request_status);
            gs.info("[EasyT] 请求记录可更新性检查: " + requestRec.isValidField('my_request_status') + 
                   ", 可写: " + requestRec.canWrite());

            // 临时禁用工作流并更新
            requestRec.setWorkflow(false);
            requestRec.my_request_status = 'Returned';
            requestRec.work_notes = "审批人要求修改，时间: " + new GlideDateTime().getDisplayValue();

            var updateSuccess = requestRec.update();
            gs.info("[EasyT] 请求记录更新操作结果: " + updateSuccess);

            if (updateSuccess) {
                // 添加审批关联验证（可选）
                gs.info("[EasyT] 验证关联关系:");
                var approvalCheck = new GlideRecord('sysapproval_approver');
                approvalCheck.addQuery('document_id', requestRec.sys_id);
                approvalCheck.query();
                gs.info("[EasyT] 找到关联的审批记录数: " + approvalCheck.getRowCount());

                gs.addInfoMessage("已退回请求，等待用户修改");
            } else {
                gs.logError("[EasyT] 更新请求记录失败！最后错误: " + requestRec.getLastErrorMessage());
                gs.addErrorMessage("无法更新请求状态，请联系管理员");
            }
        } else {
            // 增强错误处理：检查document_id是否指向其他表
            gs.logError("[EasyT] 错误：未找到关联的请求记录，document_id = " + current.document_id);
            var checkTables = ['task', 'sc_request', 'sc_req_item'];
            checkTables.forEach(function(table) {
                var tempRec = new GlideRecord(table);
                if (tempRec.get(current.document_id)) {
                    gs.logError("[EasyT] ⚠️ document_id实际指向表: " + table);
                }
            });
            gs.addErrorMessage("系统错误：找不到原始请求记录");
        }

        // 3. 刷新页面
        action.setRedirectURL(current);
    } catch(e) {
        gs.logError("[EasyT] 严重错误: " + e);
        gs.addErrorMessage("操作失败: " + (e.message || "未知错误"));
        // 记录完整堆栈信息
        gs.error(gs.getStack());
    }
})(current, action);
